// Projeto SM3 — metadata backfill for CURRENT production-ready media.
// No AI call. Uses media-worker deterministic process-path only.

const mediaRows = $input.all().map(i => i.json);
const contentRows = $('READ — PRODUCTION READY CONTENT').all().map(i => i.json);

const targetIds = new Set();

for (const c of contentRows) {
  const productionReady =
    String(c.ROUTING_TARGET || '').trim().toUpperCase() === 'PRODUCTION' &&
    String(c.PRODUCTION_STATUS || '').trim().toUpperCase() === 'READY' &&
    (
      String(c.EDITORIAL_COMMITTED_STATUS || '').trim().toUpperCase() === 'APROVADO' ||
      String(c.APPROVAL_COMMITTED_STATUS || '').trim().toUpperCase() === 'APROVADO'
    );

  if (!productionReady) continue;

  const ids = String(c.BRUTOS_USADOS || '').match(/M\d{4}/g) || [];
  for (const id of ids) targetIds.add(id);
}

const eligible = mediaRows.filter(r => {
  const id = String(r.ID_MIDIA || '').trim();
  if (!targetIds.has(id)) return false;
  if (String(r.STORAGE_STATUS || '').trim().toUpperCase() !== 'ONLINE') return false;
  if (String(r.PROCESS_STATUS || '').trim().toUpperCase() === 'DEAD_LETTER') return false;

  const missing =
    !String(r.CONTENT_HASH || '').trim() ||
    !String(r.MIME_TYPE || '').trim() ||
    !String(r.TECHNICAL_METADATA_JSON || '').trim();

  return missing;
});

if (eligible.length === 0) {
  return [{
    json:{
      queue_empty:true,
      analysis_route:'NO_WORK',
      target_media_ids:[...targetIds],
      queued_at:new Date().toISOString()
    }
  }];
}

return eligible.map(r => {
  const type = String(r.TIPO || '').trim().toUpperCase();
  const route =
    type === 'FOTO' ? 'IMAGE_ORIGINAL' :
    type === 'VÍDEO' || type === 'VIDEO' ? 'VIDEO_PROXY' :
    'UNSUPPORTED';

  return {
    json:{
      ...r,
      queue_empty:false,
      analysis_route:route,
      metadata_backfill:true,
      queued_at:new Date().toISOString()
    }
  };
});

const items = $input.all().map(i => i.json);

return items.map(w => {
  const m = w.metadata || {};
  if (!w.media_id) throw new Error('METADATA_BACKFILL_BLOCK: missing media_id');
  if (!w.content_hash && !m.sha256) throw new Error(`METADATA_BACKFILL_BLOCK: missing hash for ${w.media_id}`);

  return {json:{
    ID_MIDIA:w.media_id,
    DATA_CAPTURA:String(m.captured_at || ''),
    MIME_TYPE:String(m.mime_type || ''),
    FILE_SIZE_BYTES:Number(m.bytes || 0) || '',
    CONTENT_HASH:String(w.content_hash || m.sha256 || ''),
    CAPTURED_AT_SOURCE:String(m.captured_at_source || ''),
    TECHNICAL_METADATA_JSON:JSON.stringify(m || {}),
    PROXY_STATUS:'LOCAL_READY'
  }};
});

