const now = new Date().toISOString();
const maxTries = 3;
const workflow = 'PROJETO_SM3_02C_METADATA_BACKFILL_V2';

function compactError(x) {
  const e = x.error || x;
  const code = String(e.code || e.name || x.code || 'METADATA_DRIVE_DOWNLOAD_FAILED').slice(0, 200);
  let msg = String(e.message || x.message || e.description || 'Terminal failure after retries.');
  if (msg.length > 4000) msg = msg.slice(0, 4000);
  return {code, msg};
}

return $input.all().map(item => {
  const x = item.json || {};
  const mediaId = String(x.ID_MIDIA || x.media_id || x.MEDIA_ID || '').trim();
  const projectId = String(x.ID_PROJETO || x.project_id || x.PROJECT_ID || '').trim();
  const err = compactError(x);
  const eventId = `DLQ_${Date.now()}_${mediaId || 'UNKNOWN'}_${Math.random().toString(36).slice(2, 8)}`;

  return {json:{
    EVENT_ID: eventId,
    CREATED_AT: now,
    WORKFLOW: workflow,
    NODE: 'DOWNLOAD — ORIGINAL',
    STAGE: 'METADATA_DRIVE_DOWNLOAD',
    ENTITY_TYPE: 'MEDIA',
    ENTITY_ID: mediaId || 'UNKNOWN',
    PROJECT_ID: projectId,
    MEDIA_ID: mediaId,
    CONTENT_ID: '',
    ERROR_CODE: err.code,
    ERROR_MESSAGE: err.msg,
    ATTEMPT_COUNT: maxTries,
    MAX_TRIES: maxTries,
    RETRYABLE: false,
    DISPOSITION: 'DEAD_LETTER',
    EXECUTION_ID: String($execution.id || ''),
    PAYLOAD_JSON: JSON.stringify({
      backfill_kind: 'METADATA',
      source_type: String(x.TIPO || x.kind || x.worker_kind || ''),
      file_name: String(x.ARQUIVO || x.file_name || ''),
      drive_file_id: String(x.DRIVE_FILE_ID || x.drive_file_id || ''),
      relative_path: String(x.RELATIVE_PATH || x.relative_path || '')
    }),
    RESOLVED_AT: '',
    RESOLUTION_NOTES: '',
    VERSION: 'SM3_RELIABILITY_V1',

    event_id: eventId,
    created_at: now,
    workflow,
    node: 'DOWNLOAD — ORIGINAL',
    stage: 'METADATA_DRIVE_DOWNLOAD',
    entity_type: 'MEDIA',
    entity_id: mediaId || 'UNKNOWN',
    project_id: projectId,
    media_id: mediaId,
    content_id: '',
    error_code: err.code,
    error_message: err.msg,
    attempt_count: maxTries,
    max_tries: maxTries,
    retryable: false,
    disposition: 'DEAD_LETTER',
    execution_id: String($execution.id || ''),
    payload: {
      backfill_kind: 'METADATA',
      source_type: String(x.TIPO || x.kind || x.worker_kind || ''),
      file_name: String(x.ARQUIVO || x.file_name || ''),
      drive_file_id: String(x.DRIVE_FILE_ID || x.drive_file_id || ''),
      relative_path: String(x.RELATIVE_PATH || x.relative_path || '')
    },
    version: 'SM3_RELIABILITY_V1',

    ID_MIDIA: mediaId,
    PROCESS_STATUS: 'DEAD_LETTER',
    RETRY_COUNT: Math.max(0, maxTries - 1),
    LAST_ATTEMPT_AT: now,
    LAST_ERROR_CODE: err.code,
    LAST_ERROR_MESSAGE: err.msg,
    LAST_FAILURE_STAGE: 'METADATA_DRIVE_DOWNLOAD',
    LAST_FAILURE_NODE: 'DOWNLOAD — ORIGINAL',
    NEXT_RETRY_AT: '',
    DEAD_LETTER_AT: now,
    DEAD_LETTER_ID: eventId,
    RELIABILITY_VERSION: 'SM3_RELIABILITY_V1'
  }};
});

